mkuse!{use rustc_middle :: bug ;}
mkuse!{use rustc_middle :: mir :: visit :: * ;}
mkuse!{use rustc_middle :: mir :: * ;}
mkuse!{use rustc_middle :: ty :: { self , Ty , TyCtxt } ;}
mkitem!{const INSTR_COST : usize = 5 ;}
mkitem!{const CALL_PENALTY : usize = 25 ;}
mkitem!{const LANDINGPAD_PENALTY : usize = 50 ;}
mkitem!{const RESUME_PENALTY : usize = 45 ;}
mkitem!{const LARGE_SWITCH_PENALTY : usize = 20 ;}
mkitem!{const CONST_SWITCH_BONUS : usize = 10 ;}
mkitem!{mkstruct!{# [doc = " Verify that the callee body is compatible with the caller."] # [derive (Clone)] pub (super) struct CostChecker < 'b , 'tcx > { tcx : TyCtxt < 'tcx > , typing_env : ty :: TypingEnv < 'tcx > , penalty : usize , bonus : usize , callee_body : & 'b Body < 'tcx > , instance : Option < ty :: Instance < 'tcx > > , }}}
mkitem!{mkimpl!{impl < 'b , 'tcx > CostChecker < 'b , 'tcx > { pub (super) fn new (tcx : TyCtxt < 'tcx > , typing_env : ty :: TypingEnv < 'tcx > , instance : Option < ty :: Instance < 'tcx > > , callee_body : & 'b Body < 'tcx > ,) -> CostChecker < 'b , 'tcx > { CostChecker { tcx , typing_env , callee_body , instance , penalty : 0 , bonus : 0 } } # [doc = " Add function-level costs not well-represented by the block-level costs."] # [doc = ""] # [doc = " Needed because the `CostChecker` is used sometimes for just blocks,"] # [doc = " and even the full `Inline` doesn't call `visit_body`, so there's nowhere"] # [doc = " to put this logic in the visitor."] pub (super) fn add_function_level_costs (& mut self) { if self . callee_body . basic_blocks . iter () . filter (| bbd | is_call_like (bbd . terminator ())) . count () == 1 { self . bonus += CALL_PENALTY ; } } pub (super) fn cost (& self) -> usize { usize :: saturating_sub (self . penalty , self . bonus) } fn instantiate_ty (& self , v : Ty < 'tcx >) -> Ty < 'tcx > { if let Some (instance) = self . instance { instance . instantiate_mir (self . tcx , ty :: EarlyBinder :: bind (& v)) } else { v } } }}}
mkitem!{mkimpl!{impl < 'tcx > Visitor < 'tcx > for CostChecker < '_ , 'tcx > { fn visit_statement (& mut self , statement : & Statement < 'tcx > , location : Location) { match statement . kind { StatementKind :: Intrinsic (ref ndi) => { self . penalty += match * * ndi { NonDivergingIntrinsic :: Assume (..) => INSTR_COST , NonDivergingIntrinsic :: CopyNonOverlapping (..) => CALL_PENALTY , } ; } _ => self . super_statement (statement , location) , } } fn visit_rvalue (& mut self , rvalue : & Rvalue < 'tcx > , _location : Location) { match rvalue { Rvalue :: NullaryOp (NullOp :: UbChecks , ..) if ! self . tcx . sess . opts . unstable_opts . inline_mir_preserve_debug . unwrap_or (self . tcx . sess . ub_checks ()) => { self . bonus += CALL_PENALTY ; } Rvalue :: NullaryOp (..) => { } _ => self . penalty += INSTR_COST , } } fn visit_terminator (& mut self , terminator : & Terminator < 'tcx > , _ : Location) { match & terminator . kind { TerminatorKind :: Drop { place , unwind , .. } => { let ty = self . instantiate_ty (place . ty (self . callee_body , self . tcx) . ty) ; if ty . needs_drop (self . tcx , self . typing_env) { self . penalty += CALL_PENALTY ; if let UnwindAction :: Cleanup (_) = unwind { self . penalty += LANDINGPAD_PENALTY ; } } } TerminatorKind :: Call { func , unwind , .. } => { self . penalty += if let Some ((def_id , ..)) = func . const_fn_def () && self . tcx . intrinsic (def_id) . is_some () { INSTR_COST } else { CALL_PENALTY } ; if let UnwindAction :: Cleanup (_) = unwind { self . penalty += LANDINGPAD_PENALTY ; } } TerminatorKind :: TailCall { .. } => { self . penalty += CALL_PENALTY ; } TerminatorKind :: SwitchInt { discr , targets } => { if discr . constant () . is_some () { self . bonus += CONST_SWITCH_BONUS ; } else if targets . all_targets () . len () > 3 { self . penalty += LARGE_SWITCH_PENALTY ; } else { self . penalty += INSTR_COST ; } } TerminatorKind :: Assert { unwind , msg , .. } => { self . penalty += if msg . is_optional_overflow_check () && ! self . tcx . sess . opts . unstable_opts . inline_mir_preserve_debug . unwrap_or (self . tcx . sess . overflow_checks ()) { INSTR_COST } else { CALL_PENALTY } ; if let UnwindAction :: Cleanup (_) = unwind { self . penalty += LANDINGPAD_PENALTY ; } } TerminatorKind :: UnwindResume => self . penalty += RESUME_PENALTY , TerminatorKind :: InlineAsm { unwind , .. } => { self . penalty += INSTR_COST ; if let UnwindAction :: Cleanup (_) = unwind { self . penalty += LANDINGPAD_PENALTY ; } } TerminatorKind :: Unreachable => { self . bonus += INSTR_COST ; } TerminatorKind :: Goto { .. } | TerminatorKind :: Return => { } TerminatorKind :: UnwindTerminate (..) => { } kind @ (TerminatorKind :: FalseUnwind { .. } | TerminatorKind :: FalseEdge { .. } | TerminatorKind :: Yield { .. } | TerminatorKind :: CoroutineDrop) => { bug ! ("{kind:?} should not be in runtime MIR") ; } } } }}}

macro_rules! is_call_like_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function is_call_like in module {}", module_path!());
    };
}

mkfn!{
    is_call_like_introspect!();
    # [doc = " A terminator that's more call-like (might do a bunch of work, might panic, etc)"] # [doc = " than it is goto-/return-like (no side effects, etc)."] # [doc = ""] # [doc = " Used to treat multi-call functions (which could inline exponentially)"] # [doc = " different from those that only do one or none of these \"complex\" things."] pub (super) fn is_call_like (terminator : & Terminator < '_ >) -> bool { use TerminatorKind :: * ; match terminator . kind { Call { .. } | TailCall { .. } | Drop { .. } | Assert { .. } | InlineAsm { .. } => true , Goto { .. } | SwitchInt { .. } | UnwindResume | UnwindTerminate (_) | Return | Unreachable => false , Yield { .. } | CoroutineDrop | FalseEdge { .. } | FalseUnwind { .. } => { unreachable ! () } } }
}